p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
old=json.loads(snapshot.read_text())
if d['sections'][0]['title']==intro['title']:
 section=d['sections'].pop(0);d['sections'].insert(len(old['sections']),section)
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
assert d['sections'][:len(old['sections'])]==old['sections']
assert [s for s in d['sections'] if s['title'] in {x['title'] for x in old['sections']}]==old['sections']
for key in old:
 if key not in ['sections','sources','reviewNote']:assert d[key]==old[key],key
assert d['reviewNote'].startswith(old['reviewNote'])
assert d['sources'][:len(old['sources'])]==old['sources']
result={'informationAsOf':d['informationAsOf'],'oldSections':len(old['sections']),'newSections':len(d['sections']),'oldSectionsPreserved':True,'otherFieldsPreserved':True,'mainWords':len(' '.join(p for s in d['sections'] for p in s['paragraphs']).split())}
Path('tasks/001-russian-history-course/modern-november-validation.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(result)
